import type { ICtx, ScheduleHandle } from "@threenative/core";
import { Area3D, CharacterBody3D, CollisionShape3D, type IPhysicsContext } from "@threenative/physics";
import { type Group, Vector3 } from "three";
import { createEnemyVisual } from "../render/shapes.js";
import type { GameState } from "../state.js";
import { HOSTILE_LAYER, PLAYER_LAYER, WORLD_LAYER } from "./Player.js";

type GameCtx = ICtx<GameState, IPhysicsContext>;

const PATROL_WAYPOINTS = [
  new Vector3(-6, 0.85, 0),
  new Vector3(6, 0.85, 0),
  new Vector3(6, 0.85, -8),
  new Vector3(-6, 0.85, -8),
];

const SIGHT_RADIUS = 8;
const PATROL_SPEED = 1.5;
const CHASE_SPEED = 3.2;
const FIRE_RATE = 2.5;
const MIN_FIRE_DISTANCE = 1;

export class Enemy {
  readonly mesh: Group;
  readonly body: CharacterBody3D;
  readonly tags = ["hostile", "enemy"];
  health = 60;
  alive = true;
  #sightArea: Area3D;
  #scanHandle: ScheduleHandle | undefined;
  #fireTimer = 0;
  #patrolIndex = 0;
  #chasing = false;
  #onFire: (origin: Vector3) => void;

  constructor(
    ctx: GameCtx,
    materials: Parameters<typeof createEnemyVisual>[0],
    position: Vector3,
    options: {
      readonly onFire?: (origin: Vector3) => void;
    } = {},
  ) {
    this.#onFire = options.onFire ?? (() => undefined);
    this.mesh = createEnemyVisual(materials);
    this.mesh.position.copy(position);
    ctx.add(this.mesh);

    this.body = new CharacterBody3D({
      collisionLayer: HOSTILE_LAYER,
      collisionMask: WORLD_LAYER | PLAYER_LAYER,
      autostep: { maxHeight: 0.25, minWidth: 0.18 },
      object: this.mesh,
      physics: ctx.physics,
      shape: CollisionShape3D.capsule(0.4, 0.35),
    });

    this.#sightArea = new Area3D({
      collisionMask: PLAYER_LAYER,
      object: this.mesh,
      physics: ctx.physics,
      shape: CollisionShape3D.sphere(SIGHT_RADIUS),
    });
  }

  startPatrolling(ctx: GameCtx, playerBodyId: number): void {
    const scan = (): void => {
      if (!this.alive) return;
      const hits = this.#sightArea.getOverlappingBodies();
      this.#chasing = hits.some((body) => body.id === playerBodyId);
      this.#scanHandle = ctx.after(0.3, scan);
    };
    this.#scanHandle = ctx.after(0.3, scan);
  }

  update(ctx: GameCtx, dt: number, playerPos: Vector3): void {
    if (!this.alive) return;

    const nextWaypoint = PATROL_WAYPOINTS[this.#patrolIndex];
    if (nextWaypoint === undefined) return;

    let targetPos: Vector3;
    if (this.#chasing) {
      targetPos = playerPos;
    } else {
      targetPos = nextWaypoint;
      if (this.mesh.position.distanceTo(nextWaypoint) < 1) {
        this.#patrolIndex = (this.#patrolIndex + 1) % PATROL_WAYPOINTS.length;
      }
    }

    const direction = targetPos.clone().sub(this.mesh.position).normalize();
    const speed = this.#chasing ? CHASE_SPEED : PATROL_SPEED;
    this.body.velocity.x = direction.x * speed;
    this.body.velocity.z = direction.z * speed;
    this.body.moveAndSlide(dt);

    // Fire at player when chasing and in range
    if (this.#chasing) {
      const distance = this.mesh.position.distanceTo(playerPos);
      this.#fireTimer -= dt;
      if (this.#fireTimer <= 0 && distance >= MIN_FIRE_DISTANCE) {
        this.#fireTimer = FIRE_RATE;
        const fireOrigin = this.mesh.position.clone().add(new Vector3(0.3, 0.6, 0));
        this.#onFire(fireOrigin);
      }
    } else {
      this.#fireTimer = 0;
    }
  }

  takeDamage(amount: number): boolean {
    if (!this.alive || !Number.isFinite(amount) || amount <= 0) return false;
    this.health = Math.max(0, this.health - amount);
    if (this.health > 0) return false;
    this.alive = false;
    this.mesh.visible = false;
    return true;
  }

  debug(): Record<string, unknown> {
    return {
      alive: this.alive,
      chasing: this.#chasing,
      health: this.health,
      position: this.mesh.position.toArray(),
    };
  }

  dispose(): void {
    this.#scanHandle?.cancel();
    this.body.dispose();
    this.#sightArea.dispose();
    this.mesh.removeFromParent();
  }
}

