update(ctx: GameCtx, dt: number, playerPos: Vector3): void {
  if (!this.alive) return;

  const nextWaypoint = PATROL_WAYPOINTS[this.#patrolIndex];
  if (nextWaypoint === undefined) return;

  let targetPos: Vector3;
  if (this.#chasing) {
    targetPos = playerPos;
  } else {
    targetPos = nextWaypoint;
    if (this.mesh.position.distanceTo(nextWaypoint) < 1) {
      this.#patrolIndex = (this.#patrolIndex + 1) % PATROL_WAYPOINTS.length;
    }
  }

  const direction = targetPos.clone().sub(this.mesh.position).normalize();
  const speed = this.#chasing ? CHASE_SPEED : PATROL_SPEED;
  this.body.velocity.x = direction.x * speed;
  this.body.velocity.z = direction.z * speed;
  this.body.moveAndSlide(dt);

  // Fire at player when chasing and in range
  if (this.#chasing) {
    const distance = this.mesh.position.distanceTo(playerPos);
    this.#fireTimer -= dt;
    if (this.#fireTimer <= 0 && distance >= MIN_FIRE_DISTANCE) {
      this.#fireTimer = FIRE_RATE;
      const fireOrigin = this.mesh.position.clone().add(new Vector3(0.3, 0.6, 0));
      this.#onFire(fireOrigin);
    }
  } else {
    this.#fireTimer = 0;
  }
}

takeDamage(amount: number): boolean {
  if (!this.alive || !Number.isFinite(amount) || amount <= 0) return false;
  this.health = Math.max(0, this.health - amount);
  if (this.health > 0) return false;
  this.alive = false;
  this.mesh.visible = false;
  return true;
}

debug(): Record<string, unknown> {
  return {
    alive: this.alive,
    chasing: this.#chasing,
    health: this.health,
    position: this.mesh.position.toArray(),
  };
}

